return [
  { json: { sourceId: 'vinhomes', listingUrl: 'https://vinhomes.vn/vi/tin-tuc', includePath: '/vi/tin-tuc/', format: 'html', maxCandidates: 20 } },
  { json: { sourceId: 'vingroup-real-estate', listingUrl: 'https://vingroup.net/vi/tin-tuc-su-kien/bat-dong-san/3', includePath: '/vi/tin-tuc-su-kien/bai-viet/', format: 'html', maxCandidates: 20 } },
  ...[1, 2, 3, 4, 5].map((page) => ({ json: { sourceId: 'vinhomes-market', listingUrl: `https://market.vinhomes.vn/blog/chuyen-muc/tin-tuc${page === 1 ? '' : `?page=${page}`}`, includePath: '/blog/', format: 'html', maxCandidates: 20 } })),
];

const sourceItems = $('Official sources').all();
const pages = $input.all();
const output = [];
const decode = (text) => text
  .replace(/<[^>]*>/g, ' ')
  .replace(/&nbsp;|&#160;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&quot;|&#34;/gi, '"')
  .replace(/&#39;|&apos;/gi, "'")
  .replace(/\s+/g, ' ')
  .trim();
const isOcpPath = (pathname) => /ocean-park|ocean-city|the-empire|the-crown|the-zenpark|the-pavilion|vinh-xanh/i.test(pathname);
for (let index = 0; index < pages.length; index++) {
  const source = sourceItems[index]?.json;
  if (!source) continue;
  const response = pages[index]?.json ?? {};
  const raw = response.body ?? response.data ?? response;
  const body = typeof raw === 'string' ? raw : JSON.stringify(raw);
  const origin = source.listingUrl.match(/^https?:\/\/[^/]+/i)?.[0] ?? '';
  const listingDirectory = source.listingUrl.replace(/[^/]+(?:[?#].*)?$/, '');
  const maxCandidates = source.maxCandidates ?? 20;
  const seen = new Set();
  const addCandidate = (rawHref, rawTitle = '') => {
    const href = decode(rawHref).trim();
    let canonicalUrl = href;
    if (href.startsWith('//')) canonicalUrl = `https:${href}`;
    else if (href.startsWith('/')) canonicalUrl = `${origin}${href}`;
    else if (!/^https?:\/\//i.test(href)) canonicalUrl = `${listingDirectory}${href}`;
    canonicalUrl = canonicalUrl.split('#')[0];
    const pathname = canonicalUrl.replace(/^https?:\/\/[^/]+/i, '').split(/[?#]/)[0];
    if (!pathname.includes(source.includePath) || !isOcpPath(pathname)) return;
    if (/\/(?:tu-khoa|chuyen-muc|tai-lieu)\//i.test(pathname)) return;
    if (canonicalUrl.replace(/\/$/, '') === source.listingUrl.replace(/\/$/, '')) return;
    if (seen.has(canonicalUrl) || seen.size >= maxCandidates) return;
    const slugTitle = pathname.split('/').filter(Boolean).slice(-1)[0]?.replace(/[-_]+/g, ' ') ?? '';
    const fallbackTitle = decode(rawTitle) || slugTitle;
    if (fallbackTitle.length < 5) return;
    seen.add(canonicalUrl);
    output.push({ json: { ...source, canonicalUrl, fallbackTitle } });
  };
  if (source.format === 'sitemap') {
    const location = /<loc>([\s\S]*?)<\/loc>/gi;
    let match;
    while ((match = location.exec(body)) && seen.size < maxCandidates) addCandidate(match[1]);
    continue;
  }
  const anchor = /<a\b[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;
  let match;
  while ((match = anchor.exec(body)) && seen.size < maxCandidates) addCandidate(match[1], match[2]);
}
return output;

const candidates = $('Extract article links').all();
const pages = $input.all();
const output = [];
const clean = (value = '') => value
  .replace(/<[^>]*>/g, ' ')
  .replace(/&nbsp;|&#160;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&quot;|&#34;/gi, '"')
  .replace(/&#39;|&apos;/gi, "'")
  .replace(/\s+/g, ' ')
  .trim();
const fold = (value = '') => clean(value).normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/đ/g, 'd').replace(/Đ/g, 'D').toLowerCase();
const escape = (value) => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const meta = (html, name) => {
  const key = escape(name);
  const first = html.match(new RegExp(`<meta[^>]+(?:property|name)=[\"']${key}[\"'][^>]+content=[\"']([^\"']*)[\"']`, 'i'));
  const reverse = html.match(new RegExp(`<meta[^>]+content=[\"']([^\"']*)[\"'][^>]+(?:property|name)=[\"']${key}[\"']`, 'i'));
  return clean(first?.[1] ?? reverse?.[1] ?? '');
};
for (let index = 0; index < pages.length; index++) {
  const candidate = candidates[index]?.json;
  if (!candidate) continue;
  const response = pages[index]?.json ?? {};
  const raw = response.body ?? response.data ?? response;
  const html = typeof raw === 'string' ? raw : JSON.stringify(raw);
  const title = meta(html, 'og:title') || meta(html, 'twitter:title') || candidate.fallbackTitle;
  if (!title || title.length < 5) continue;
  const summary = meta(html, 'og:description') || meta(html, 'description') || null;
  const imageUrl = meta(html, 'og:image') || null;
  const publishedRaw = meta(html, 'article:published_time') || (html.match(/"datePublished"\s*:\s*"([^"]+)"/i)?.[1] ?? null);
  const haystack = `${title} ${summary ?? ''}`.toLocaleLowerCase('vi');
  const scope = fold(`${candidate.canonicalUrl} ${title} ${summary ?? ''}`);
  const projectNames = new Set();
  const isOceanCity = /\bocean city\b/.test(scope);
  const roomNumber = /\bocean park [23] (?:phong ngu|pn|bedroom)\b/.test(scope);
  const isOcp3 = /\b(?:vinhomes )?ocean park 3\b/.test(scope) && !/\bocean park 3 (?:phong ngu|pn|bedroom)\b/.test(scope) || /\bthe crown\b/.test(scope);
  const isOcp2 = /\b(?:vinhomes )?ocean park 2\b/.test(scope) && !/\bocean park 2 (?:phong ngu|pn|bedroom)\b/.test(scope) || /\bthe empire\b/.test(scope);
  const isOcp1 = /\bocean park 1\b|\bocean park gia lam\b|\bthe zenpark\b|\bthe pavilion\b|\bsapphire [12]\b/.test(scope) || roomNumber || (/\b(?:vinhomes )?ocean park\b/.test(scope) && !isOcp2 && !isOcp3);
  if (isOcp1) projectNames.add('Vinhomes Ocean Park');
  if (isOcp2) projectNames.add('Vinhomes Ocean Park 2');
  if (isOcp3) projectNames.add('Vinhomes Ocean Park 3');
  if (projectNames.size === 0 && isOceanCity) {
    projectNames.add('Vinhomes Ocean Park');
    projectNames.add('Vinhomes Ocean Park 2');
    projectNames.add('Vinhomes Ocean Park 3');
  }
  if (projectNames.size === 0) continue;
  let topic = 'official_update';
  if (/ưu đãi|khuyến mãi|chính sách bán hàng|chiết khấu/.test(haystack)) topic = 'promotion';
  else if (/tiến độ|khởi công|bàn giao|thi công/.test(haystack)) topic = 'project_progress';
  else if (/hạ tầng|đường vành đai|cao tốc|sân bay|cầu /.test(haystack)) topic = 'infrastructure';
  else if (/tiềm năng|đầu tư|tăng trưởng|thị trường/.test(haystack)) topic = 'market_potential';
  output.push({ json: { source_id: candidate.sourceId, canonical_url: candidate.canonicalUrl, title: clean(title), summary: summary ? clean(summary).slice(0, 2000) : null, image_url: imageUrl, topic, project_names: [...projectNames], published_at: publishedRaw } });
}
return output;
